import {renderLearningPath,renderCompletedProgress} from './path-view.mjs';
import {renderBasics} from './basics-view.mjs';
import {wordClassLabel} from './word-class-labels.mjs';
import {offlineCacheMessage,hostedUrl} from './runtime.mjs';
import {h,icon,button as btn,plural,spoken,teachingText} from './ui.mjs';
import {levels,lessons,lessonById,languageNotes,glossary,needsReview,importSummary,documentImportSummary,documentNeedsReview,getWordEntries,isMarked} from './course.mjs';
import {getLearnerLevel,getAchievements,activeStreak} from './engine.mjs';
import {getDanishVoices,voiceStatus} from './speech.mjs';
import {renderMemoryPlan,renderMemoryStats,renderMethod} from './memory-view.mjs';
import {renderIllustration} from './illustrations.mjs';
import {renderWordLab} from './wordlab-view.mjs';
import {lessonGroups} from './lesson-navigation.mjs';
import {renderPronunciation} from './pronunciation-view.mjs';
import {renderReference} from './reference-view.mjs';
import {renderLocalCopies} from './copies-view.mjs';

export const modeNames={easy:'С вариантами',mixed:'Смешанный',expert:'Без подсказок'};
export const count=(n,forms=['слово','слова','слов'])=>`${n} ${plural(n,forms)}`;
export const heading=(title,text='',action='')=>`<div class="page-heading"><div><h1>${title}</h1>${text?`<p>${text}</p>`:''}</div>${action}</div>`;
export const empty=(title,text='')=>`<div class="empty">${icon('cards')}<h3>${title}</h3><p>${text}</p></div>`;
export function levelTabs(state,available=Object.keys(levels),effective=state.settings.level){
 return `<div class="level-tabs" role="group" aria-label="Сложность материала">${available.map(level=>`<button data-action="level" data-value="${level}" class="${effective===level?'active':''}" aria-pressed="${effective===level}"><b>${level}</b><span>${levels[level].name}</span></button>`).join('')}</div>`;
}
export function modes(state){return `<div class="mode-switch" role="group" aria-label="Режим упражнений">${Object.entries(modeNames).map(([id,name])=>`<button data-action="mode" data-value="${id}" aria-pressed="${state.settings.mode===id}" class="${state.settings.mode===id?'active':''}">${icon(id==='easy'?'cards':id==='mixed'?'layers':'bolt')}<span>${name}</span></button>`).join('')}</div>`;}
const mastered=(l,s)=>(s.completed[l.id]?.best||0)>=80;
function lessonCard(l,s){const done=s.completed[l.id],good=mastered(l,s);return `<article class="lesson-card ${l.color||'violet'} ${done?'is-completed':''} ${good?'is-mastered':''}" data-card-action="lesson-intro" data-id="${l.id}"><div class="lesson-card-top"><span class="topic-icon">${icon(done?'check':l.icon)}</span><span class="pill ${good?'mint':''}">${done?`${good?'Закреплено':'Пройдено'} · ${done.best}%`:l.level}</span></div><h3>${h(l.title)}</h3><p>${h(l.subtitle)}</p><button class="lesson-card-bottom" data-action="lesson-intro" data-id="${l.id}" aria-label="${done?'Повторить':'Начать'}: ${h(l.title)}"><span>${l.items.length} заданий${done?` · пройдено ${done.attempts} ${plural(done.attempts,['раз','раза','раз'])}`:''}</span><span class="round-button" aria-hidden="true">${icon(done?'repeat':'arrow')}</span></button></article>`;}
export function renderLessonCollection(ls,s){const group=lessonGroups(ls,s),next=group.remaining[0]||group.completed.find(l=>!mastered(l,s));return `${next?`<div class="next-lesson-panel"><div><small>${s.completed[next.id]?'Закрепить тему':'Следующая тема'}</small><b>${h(next.title)}</b></div>${btn(`${s.completed[next.id]?'Повторить':'Продолжить'} ${icon('arrow')}`,'lesson-intro','primary',`data-id="${next.id}"`)}</div>`:ls.length?'<div class="info-panel">Все темы этого раздела закреплены. Можно перейти к следующему уровню или открыть пройденные уроки.</div>':''}<div class="lesson-grid">${group.remaining.map(l=>lessonCard(l,s)).join('')}</div>${group.completed.length?`<details class="completed-lessons"><summary>${icon('check')}<span>Пройденные уроки · ${group.completed.length}<small class="muted"> · закреплено ${group.mastered}</small></span></summary><div class="lesson-grid">${group.completed.map(l=>lessonCard(l,s)).join('')}</div></details>`:''}`;}

function ruleArt(){return `<div class="rule-art" aria-label="После I dag глагол работает на второй позиции"><div class="paper-label">ПОРЯДОК СЛОВ · V2</div><div class="word-line" lang="da"><span>Jeg</span> <span class="mint">arbejder</span> <span>i dag.</span></div><div class="art-arrow">${icon('repeat')}<span>Начинаем со времени</span></div><div class="word-line" lang="da"><span class="yellow">I dag</span> <span class="mint">arbejder</span> <span class="pink">jeg.</span></div><p>Глагол сохраняет вторую позицию.</p></div>`;}
function home(c){const {state:s,due,todayXP}=c;return `${heading(s.settings.name?`Hej, ${h(s.settings.name)}!`:'Твой датский — шаг за шагом.','Выбери уровень и иди по маршруту. Приложение запомнит, где ты остановился.')}${renderLearningPath(c,modes(s))}<div class="home-status"><span>Сегодня: <b>${todayXP} / ${s.settings.goal} XP</b></span><span>Опыт: ${getLearnerLevel(s.xp).level}</span><button class="text-button" data-action="edit-profile">${s.settings.name?'Изменить имя':'Как к тебе обращаться?'}</button></div><div class="home-tools"><button class="btn secondary" data-page="basics">${icon('book')} Числа и чтение</button><button class="btn secondary" data-page="grammar">${icon('layers')} Все темы грамматики</button><button class="btn secondary" data-action="lab-show-classes">${icon('cards')} Части речи · Ordklasser</button><button class="btn secondary" data-page="dictionary">${icon('bookmark')} Мои слова</button><button class="btn secondary" data-page="pronunciation">${icon('sound')} Звуки и произношение</button></div><details class="home-repeat" ${due.length?'open':''}><summary>${icon('repeat')} Повторение · ${due.length} сейчас</summary>${renderMemoryPlan(c)}</details><div class="bottom-strip"><span>${icon('check')} ${c.offlineEdition?'Прогресс сохраняется в этом браузере. Для переноса выгрузи JSON в настройках.':'Прогресс сохраняется на устройстве и синхронизируется после входа.'}</span><button data-page="settings">Настройки ${icon('arrow')}</button></div>`;}

function grammar(c){const s=c.state,ls=lessons.filter(l=>l.kind==='grammar'&&l.level===s.settings.level);return `${heading('Грамматика, которая складывается.','Правило → пример → практика → разбор ошибки. От первых фраз до C1.')}${s.settings.level==='A1'?ruleArt():''}<div class="reference-shortcuts"><button class="btn secondary" data-page="basics">Числа и чтение</button>${btn('Таблица глаголов','open-verbs','secondary')}${btn('Лексика по ситуациям','open-daily','secondary')}${btn('Классы частых слов','open-common','secondary')}${btn('Времена','open-tenses','secondary')}${btn('Сравнение и количество','open-adjectives','secondary')}${btn('Приставки и частицы','open-particles','secondary')}</div><button class="wordlab-entry compact" data-action="lab-show-classes"><span class="wordlab-entry-icon">${icon('layers')}</span><span><b>Ordklasser · Классы слов</b><small>Как различать существительные, глаголы и другие классы</small></span>${icon('arrow')}</button><div class="course-toolbar">${levelTabs(s)}<span class="pill purple">${ls.filter(l=>mastered(l,s)).length} / ${ls.length} закреплено</span></div><div class="practice-toolbar"><span>${icon('target')} Как будешь отвечать?</span>${modes(s)}</div>${renderLessonCollection(ls,s)}<div class="section-title space-top"><div><h2>Применить в ситуации</h2><p>Знакомые конструкции в повседневных разговорах.</p></div></div>${renderLessonCollection(lessons.filter(l=>l.kind==='context'&&l.level===s.settings.level),s)||'<div class="info-panel">Выбери профессиональное общение в разделе «Живая речь».</div>'}<p class="fine-print">A1–C1 обозначают сложность практики, а не полный сертифицированный курс.</p>`;}
function conversation(c){const s=c.state,level=s.settings.level==='A1'?'A2':s.settings.level;return `${heading('Так говорят в жизни.','Что значит фраза, где она уместна и как отличается от письменного датского.')}<div class="reference-shortcuts">${btn('Ответить в диалоге · B2–C1','open-dialogues','secondary')}${btn('Разговорные фразы по ситуациям','open-spoken','secondary')}${btn('Частицы и выражения','open-particles','secondary')}${btn('Произношение','open-pronunciation','secondary')}${btn('Сленг и грубая речь','open-informal','secondary')}</div><div class="conversation-banner"><span class="topic-icon">${icon('chat')}</span><div><h2>Понимай реплики целиком.</h2><p>Разговорные формы отмечены отдельно: их не стоит переносить в официальное письмо.</p></div></div>${levelTabs(s,['A2','B1','B2','C1'],level)}${modes(s)}${['B2','C1'].includes(level)?`<section class="dialogue-lessons"><div class="section-title"><div><h2>Твой ответ в диалоге</h2><p>Пойми собеседника и ответь целым предложением.</p></div></div>${renderLessonCollection(lessons.filter(l=>l.roleplay&&l.level===level),s)}</section><div class="section-title space-top"><h2>Фразы и конструкции</h2></div>`:''}${renderLessonCollection(lessons.filter(l=>l.kind==='conversation'&&!l.roleplay&&l.level===level),s)}<div class="section-title space-top"><h2>На слух и на письме</h2></div><div class="notes-grid">${languageNotes.map(n=>`<article class="panel language-note"><span class="pill blue">${h(n.level||'Живая речь')}</span><h3>${h(n.title)}</h3><div class="register-row"><span>На письме</span><b lang="da">${h(n.formal)}</b></div><div class="register-row spoken"><span>В разговоре</span><b lang="da">${h(n.spoken)}</b></div><p>${teachingText(n.meaning)}</p><small>${teachingText(n.note)}</small></article>`).join('')}</div><div class="section-title space-top"><h2>Выражения целиком</h2></div><div class="notes-grid">${glossary.map(p=>`<article class="panel idiom"><div><h3 lang="da">${h(p.da)}</h3><button class="icon-button" data-action="speak-text" data-text="${h(p.da)}" title="Послушать выражение">${icon('sound')}</button></div><b>${h(p.ru)}</b><p>${teachingText(p.note)}</p></article>`).join('')}</div>`;}
export function wordCard(p,s){const difficult=isMarked(p,s.difficult),saved=isMarked(p,s.bookmarks);return `<article class="word-card panel ${difficult?'is-difficult':''}" data-card-action="word-detail" data-id="${p.id}">${renderIllustration(p,'card-picture')}<div class="word-card-top"><span class="word-tag">${h(p.kind==='wordclass'?`Класс слова: ${p.focus.target}`:p.kind==='meaning'?'Значение в контексте':p.source==='personal'?'Личное слово':p.tag||p.level||'Из файла')}</span><div class="mini-actions"><button class="icon-button ${saved?'marked':''}" data-action="bookmark" data-id="${p.id}" aria-pressed="${saved}" title="${saved?'Убрать из избранного':'Сохранить в избранное'}">${icon('bookmark')}</button><button class="icon-button" data-action="speak" data-id="${p.id}" title="Послушать произношение">${icon('sound')}</button></div></div><button class="word-title" data-action="word-detail" data-id="${p.id}" lang="da">${h(p.da)}</button><p class="word-translation">${h(p.ru)}</p>${wordClassLabel(p.wordClass)?`<div class="word-class-name">${teachingText(wordClassLabel(p.wordClass))}</div>`:''}${p.verified===false?'<span class="pill yellow">Перевод из файла · проверить</span>':''}${p.association?`<div class="association">${icon('brain')}<p>${h(p.association)}</p></div>`:''}${p.exampleDa?`<div class="word-example"><p lang="da">${h(p.exampleDa)}</p><small>${h(p.exampleRu||'')}</small></div>`:''}<div class="word-card-bottom"><button class="remember-button ${difficult?'active':''}" data-action="difficult" data-id="${p.id}" aria-pressed="${difficult}">${icon(difficult?'check':'repeat')}${difficult?'В сложных':'Не запомнил'}</button><button class="text-button" data-action="word-detail" data-id="${p.id}">Разбор ${icon('arrow')}</button></div></article>`;}
function dictionary(c){const s=c.state,tabs=[['file','Из твоего файла'],['all','Все слова'],['illustrated','С картинками'],['personal','Добавленные'],['difficult','Не запомнил'],['saved','Избранное'],['check','Проверить записи']];return `${heading('Слова становятся твоими.','Твои переводы, личные ассоциации и фразы в контексте.',btn(`${icon('plus')} Добавить слово`,'add-word'))}<div class="reference-shortcuts">${btn('Лексика по ситуациям','open-daily','secondary')}${btn('Классы частых слов','open-common','secondary')}${btn('Таблица глаголов','open-verbs','secondary')}</div><button class="wordlab-entry compact" data-page="wordlab"><span class="wordlab-entry-icon">${icon('layers')}</span><span><b>Значения и классы слов</b><small>Разбери слово в контексте и проверь себя</small></span>${icon('arrow')}</button><div class="import-strip"><span class="file-icon">${icon('cards')}</span><div><b>Твои учебные словари</b><p>Первый файл: ${importSummary.imported} записей · два новых словаря: ${documentImportSummary.importedEntries} проверенных слов и выражений · повторы объединены</p></div><button class="text-button" data-action="start-file">Тренировать ${icon('arrow')}</button></div><div class="filter-tabs" role="group" aria-label="Группа слов">${tabs.map(([id,label])=>`<button class="${c.wordFilter===id?'active':''}" data-action="word-filter" data-value="${id}" aria-pressed="${c.wordFilter===id}">${label}</button>`).join('')}</div>${c.wordFilter==='check'?`<div class="notice warning">${icon('info')}<span>Неоднозначные записи и заметки без надёжного датского написания не используются в заданиях. Верное слово можно добавить вручную.</span></div><div class="source-review">${[...needsReview,...documentNeedsReview].slice(0,c.wordLimit).map(p=>`<details class="panel"><summary>${h(String(p.original||'Запись').slice(0,150))}</summary><p>${h(p.original)}</p><small>${h(p.note||p.reason)}</small></details>`).join('')}</div>${needsReview.length+documentNeedsReview.length>c.wordLimit?`<div class="load-more">${btn('Показать ещё','more-words','secondary')}</div>`:''}`:`<div class="dictionary-toolbar"><label class="search-box">${icon('search')}<input id="word-search" type="search" value="${h(c.query)}" placeholder="Слово или перевод" aria-label="Поиск слова"></label><span>${count(c.words.length)}</span>${btn('Тренировать группу','train-filter','secondary')}</div><div class="word-grid">${c.words.slice(0,c.wordLimit).map(p=>wordCard(p,s)).join('')||empty('Пока ничего нет.','Добавь слово или измени поиск.')}</div>${c.words.length>c.wordLimit?`<div class="load-more">${btn('Показать ещё 24','more-words','secondary')}</div>`:''}`}`;}
function review(c){const s=c.state;return `${heading('Закрепляй в нужный момент.','Небольшие наборы с переходом от узнавания к самостоятельному ответу.')}${renderMemoryPlan(c)}${renderMemoryStats(c)}<div class="section-title space-top"><h2>Выбрать материал самому</h2></div><div class="review-options"><button class="quick-card peach" data-action="practice-difficult">${icon('brain')}<span><b>Не запомнил</b><small>${count(s.difficult.length)} отмечено вручную</small></span>${icon('arrow')}</button><button class="quick-card mint" data-action="practice-saved">${icon('bookmark')}<span><b>Избранное</b><small>Сохранённые тобой слова</small></span>${icon('arrow')}</button></div><div class="button-row">${btn('Знакомые задания','practice-known','secondary')}${btn('Слова из файла','start-file','secondary')}</div><p class="field-note">Для этих тренировок действует выбранный в настройках ручной режим. Они доступны и после дневного предела нового материала.</p>${c.due.length?`<div class="section-title space-top"><h2>Сейчас в повторении</h2></div><div class="word-grid">${c.due.slice(0,8).map(p=>wordCard(p,s)).join('')}</div>`:''}`;}
function progress(c){const s=c.state,learner=getLearnerLevel(s.xp),awards=getAchievements(s),done=Object.keys(s.completed).filter(id=>lessonById[id]);return `${heading('Видно, что уже получилось.','Пройденные темы, накопленные XP и достижения сохраняются.')}<div class="level-panel"><div class="level-medal">${icon('spark')}<b>${learner.level}</b></div><div><span class="eyebrow">УРОВЕНЬ ОПЫТА</span><h2>${h(learner.name)}</h2><p>${learner.into} / ${learner.next} XP до следующего</p><div class="meter"><span style="width:${learner.progress*100}%"></span></div></div><span class="level-total">${s.xp}<small>ВСЕГО XP</small></span></div><div class="stats-grid">${[[done.length,'уроков пройдено','book'],[done.filter(id=>mastered(lessonById[id],s)).length,'закреплено на 80%+','check'],[activeStreak(s),'дней в текущей серии','flame'],[Object.keys(s.reviews).length,'фраз в повторении','cards']].map(([n,label,ic])=>`<div class="panel stat-card">${icon(ic)}<b>${n}</b><span>${label}</span></div>`).join('')}</div>${renderCompletedProgress(s)}${renderMemoryStats(c)}<div class="section-title space-top"><h2>Достижения</h2><span>${awards.filter(a=>a.earned).length} / ${awards.length}</span></div><div class="achievement-grid">${awards.map(b=>`<article class="achievement panel ${b.earned?'earned':''}"><span class="achievement-icon">${icon(b.icon)}</span><div><h3>${h(b.title)}</h3><p>${h(b.description)}</p><div class="meter"><span style="width:${b.progress/b.target*100}%"></span></div><small>${b.progress} / ${b.target}${b.earned?' · Получено':''}</small></div></article>`).join('')}</div><div class="section-title space-top"><h2>Твоя карта тем</h2></div><div class="topic-progress">${Object.keys(levels).map(level=>{const ls=lessons.filter(l=>l.level===level),n=ls.filter(l=>mastered(l,s)).length;return `<button class="panel topic-progress-row" data-action="open-level" data-value="${level}"><b>${level}</b><span>${levels[level].name}</span><div class="meter"><span style="width:${n/ls.length*100}%"></span></div><small>${n} / ${ls.length}</small>${icon('arrow')}</button>`;}).join('')}</div><p class="fine-print">Уровень опыта и сложность A1–C1 — разные показатели. Можно сразу открыть подходящую тему.</p>`;}
function settings(c){const s=c.state;return `${heading('Удобно читать. Удобно учиться.','Настройки применяются сразу и сохраняются.')}${c.cloudPlan||''}<div class="settings-grid"><section class="panel settings-card"><h2>Текст и оформление</h2><label for="font-size">Размер основного текста</label><select id="font-size" data-setting="fontSize">${[16,18,20].map(n=>`<option value="${n}" ${s.settings.fontSize===n?'selected':''}>${n} px${n===18?' — стандартный':''}</option>`).join('')}</select><p class="text-preview" lang="da">Jeg lærer dansk i mit eget tempo.<small lang="ru">Я учу датский в своём темпе.</small></p><label for="theme">Тема</label><select id="theme" data-setting="theme"><option value="light" ${s.settings.theme==='light'?'selected':''}>Светлая</option><option value="dark" ${s.settings.theme==='dark'?'selected':''}>Тёмная</option></select><label for="goal">Дневная цель</label><select id="goal" data-setting="goal">${[30,60,100].map(n=>`<option value="${n}" ${s.settings.goal===n?'selected':''}>${n} XP</option>`).join('')}</select><label for="new-limit">Новых заданий в день · практика памяти</label><select id="new-limit" data-setting="newPerDay">${[3,6,10].map(n=>`<option value="${n}" ${s.settings.newPerDay===n?'selected':''}>${n} новых</option>`).join('')}</select><p class="field-note">Повторения идут первыми. Новое вводится небольшими порциями, до двух за один набор. Ручные уроки не ограничены этим планом.</p><h3 class="space-top">Режим упражнений</h3>${modes(s)}<p class="field-note">С вариантами — лёгкий вход. Смешанный — ещё письмо, аудирование и сборка. Без подсказок — самостоятельный ввод, включая B2 и C1.</p></section><div class="settings-column"><section class="panel settings-card"><h2>Произношение</h2><p class="voice-status ${getDanishVoices().length?'available':''}">${icon('sound')}${h(voiceStatus(s.settings.voiceUri))}</p><label for="voice">Датский голос устройства</label><select id="voice" data-setting="voiceUri">${voiceOptions(s.settings.voiceUri)}</select><label for="rate">Скорость речи</label><select id="rate" data-setting="rate">${[[0.7,'Медленно'],[0.85,'Комфортно'],[1,'Обычная скорость']].map(([v,n])=>`<option value="${v}" ${s.settings.rate===v?'selected':''}>${n}</option>`).join('')}</select>${btn(`${icon('sound')} Проверить голос`,'test-sound','secondary')}<button class="btn secondary" data-page="pronunciation">Практика произношения</button><p class="field-note">Нужен датский голос браузера или системы. Если его нет, задания доступны с текстом. В разделе произношения можно записать себя и сравнить вручную. Запись не отправляется на сервер; автоматической оценки акцента нет. Кириллические записи из заметок не выдаются за точную транскрипцию.</p></section><section class="panel settings-card"><h2>Твой прогресс</h2><p>${c.offlineEdition?'Сохраняются уроки, ошибки, избранное, личные слова и настройки в этом браузере. Облачной синхронизации у HTML-файла нет. Для переноса результатов выгрузи JSON и загрузи его на другом устройстве.':'Сохраняются уроки, ошибки, избранное, личные слова и настройки. Синхронизация работает в опубликованном приложении после входа в тот же аккаунт. При отсутствии сети остаётся копия устройства.'}</p><div class="button-row">${btn(`${icon('download')} Выгрузить`,'export','secondary')}${btn(`${icon('upload')} Загрузить`,'import','secondary')}${!c.localCopies&&c.recovery?btn('Исходная копия','export-recovery','secondary'):''}</div>${renderLocalCopies(c.localCopies)}<input id="progress-file" type="file" accept=".json,application/json" hidden><p class="field-note">Очистка данных браузера удаляет локальный прогресс. JSON-файл позволяет перенести его на другое устройство.</p></section></div></div>${c.offlineEdition?`<section class="panel install-panel"><div><h3>Один HTML-файл</h3><p>На ПК открой Danskdag.html в Chrome или Edge. Для значка на рабочем столе в полном архиве есть «Создать_ярлык.cmd». На телефоне открытие локального HTML зависит от браузера; для значка приложения открой сайт и добавь его на главный экран.</p></div><a class="btn secondary" href="${hostedUrl}" target="_blank" rel="noopener noreferrer">Открыть сайт</a></section>`:`<section class="panel install-panel"><div><h3>Значок приложения на телефоне и ПК</h3><p>На Android: меню Chrome → «Установить приложение» или «Добавить на главный экран». На iPhone: Safari → «Поделиться» → «На экран Домой». На ПК: меню браузера → «Установить страницу как приложение». Для первого запуска нужен интернет.</p><p class="field-note" data-offline-status>${h(offlineCacheMessage(c.offlineReady))}</p></div>${c.installEvent?btn('Установить','install','secondary'):''}</section>`}<section class="panel install-panel"><div><h3>Поделиться с друзьями</h3><p>Ссылка одна, а личный прогресс у каждого свой. Если доступ закрыт, владелец разрешает вход через настройки доступа Sites.</p></div>${btn('Копировать ссылку','copy-link','secondary')}</section><p class="fine-print">Danskdag 1.9.2 · ${lessons.length} ${plural(lessons.length,['урок','урока','уроков'])} · грамматика A1–C1 · личный словарь</p>`;}
export function renderView(page,context){return ({learn:home,grammar,dictionary,review,conversation,progress,settings,basics:c=>renderBasics(c,renderLessonCollection),pronunciation:renderPronunciation,method:renderMethod,wordlab:c=>renderWordLab(c,modes(c.state)),forms:c=>renderReference(c,renderLessonCollection),pd3:c=>c.pd3View()}[page]||home)(context);}

export function voiceOptions(preferred){return `<option value="">Автоматически</option>${getDanishVoices().map(v=>`<option value="${h(v.voiceURI)}" ${preferred===v.voiceURI?'selected':''}>${h(v.name)}</option>`).join('')}`;}
